<?php require_once '../config/auth.php';require_role('kepala_sekolah');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->beginTransaction();$pdo->exec("UPDATE tahun_ajaran SET status='Tidak Aktif'");$q=$pdo->prepare("UPDATE tahun_ajaran SET status='Aktif' WHERE id_tahun_ajaran=?");$q->execute([(int)$_POST['id']]);$pdo->commit();flash('success','Status tahun ajaran diperbarui.');redirect('tahun_ajaran.php');}$rows=$pdo->query('SELECT * FROM tahun_ajaran ORDER BY id_tahun_ajaran DESC')->fetchAll();$page_title='Kelola Tahun Ajaran';require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php'; ?><h2>Kelola Tahun Ajaran</h2><div class="card p-3"><table class="table"><thead><tr><th>Tahun</th><th>Semester</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['tahun_ajaran']) ?></td><td><?= e($r['semester']) ?></td><td><?= e($r['status']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id_tahun_ajaran'] ?>"><button class="btn btn-sm btn-primary">Jadikan aktif</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php require '../includes/footer.php';
